// ./src/components/CombinedParallaxSection.js
import React, { useRef, useState, useEffect } from 'react';
import { motion } from 'framer-motion';

export default function CombinedParallaxSection({ image, children, height = "500px", scrollSpeed = 0.2 }) {
  const sectionRef = useRef(null);
  const [offsetY, setOffsetY] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      if (!sectionRef.current) return;
      const rect = sectionRef.current.getBoundingClientRect();
      const windowHeight = window.innerHeight;
      const scrollRelative = ((windowHeight / 2 - rect.top - rect.height / 2) * scrollSpeed) || 0;
      setOffsetY(scrollRelative);
    };

    window.addEventListener("scroll", handleScroll);
    window.addEventListener("resize", handleScroll);
    handleScroll();
    return () => {
      window.removeEventListener("scroll", handleScroll);
      window.removeEventListener("resize", handleScroll);
    };
  }, [scrollSpeed]);

  return (
    <section ref={sectionRef} className="relative w-full overflow-hidden" style={{ height }}>
      <motion.div
        className="absolute inset-0 bg-no-repeat bg-center"
        style={{ backgroundImage: `url(${image})`, backgroundSize: "110%" }}
        animate={{
          backgroundPositionX: ["50%", "50.2%", "49.8%", "50%"],
          backgroundPositionY: [
            `${50 + offsetY}%`,
            `${50 + offsetY + 1}%`,
            `${50 + offsetY - 1}%`,
            `${50 + offsetY}%`,
          ],
          backgroundSize: ["150%", "150%", "150%"],
        }}
        transition={{
          duration: 10,
          repeat: Infinity,
          repeatType: "mirror",
          ease: "easeInOut",
        }}
      />
      <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
        {children}
      </div>
    </section>
  );
}
